import base64,gzip,json,re
from pathlib import Path
root=Path('.')
www=root/'app/src/main/assets/www'
p=www/'content-data.js'
s=p.read_text()
m=re.search(r"window\.NS_CONTENT\s*=\s*(\{.*\});\s*\n\}\)\(\);?\s*$",s,re.S)
if not m: raise SystemExit('Cannot parse NS_CONTENT')
db=json.loads(m.group(1))
delta=json.loads(gzip.decompress(base64.b64decode('')).decode())
db['MEDICAL_SOURCES'].update(delta['source_update'])
db['MEDICAL_SOURCES'].update(delta['source_add'])
for subj,recs in delta['lessons'].items():
    arr=db['LESSONS'][subj]; by={x['id']:i for i,x in enumerate(arr)}
    for rid,obj in recs.items():
        if rid not in by: raise SystemExit(f'Lesson missing: {subj}/{rid}')
        arr[by[rid]]=obj
for field,key in [('QUESTIONS','questions'),('FLASHCARDS','flashcards')]:
    arr=db[field]; by={x['id']:i for i,x in enumerate(arr)}
    for rid,obj in delta[key].items():
        if rid not in by: raise SystemExit(f'{field} missing: {rid}')
        arr[by[rid]]=obj
db['AUDIT_META_FARMA']=delta['audit_meta_farma']
p.write_text("/* NurseStudy content database — medically audited v0.10 (Farmakologia). */\n(function(){\n  'use strict';\n  window.NS_CONTENT = "+json.dumps(db,ensure_ascii=False,indent=2)+";\n})();\n")
bg=root/'app/build.gradle'
t=bg.read_text().replace('versionCode 9','versionCode 10').replace("versionName '0.9.0-test'","versionName '0.10.0-test'")
bg.write_text(t)
sw=www/'sw.js'
sw.write_text(sw.read_text().replace('nursestudy-v9-interna-audit','nursestudy-v10-farma-audit'))
